/**
 * IEEE GBPIET certificate template (fully self-contained: images are embedded as base64).
 *
 * Parameters
 *   name          string  - recipient name
 *   branch        string  - e.g. "CSE"
 *   event         string  - event name
 *   date          string  - event date, e.g. "10 October 2026"
 *   certificateId string  - printed bottom-right, e.g. "01/001/IEEE/10/2026"
 *   position      number|string (optional) - 1, "1", "1st", ... -> Position Holders version
 *                 leave empty/undefined -> Participation version
 *   issueDate     (accepted for compatibility, not shown in this design)
 *
 * Puppeteer:
 *   await page.setContent(html, { waitUntil: "networkidle0" });   // waits for Google Fonts
 *   await page.pdf({ width: "962px", height: "680px", printBackground: true, pageRanges: "1" });
 */

// ---------------- EMBEDDED IMAGES ----------------
const ART_TL =
  "data:image/png;base64,";

const ART_TR =
  "data:image/png;base64,";

const ART_BL =
  "data:image/png;base64,";

const ART_BR =
  "data:image/png;base64,";

const WATERMARK =
  "data:image/png;base64,";

const LOGO_COLLEGE =
  "data:image/png;base64,";

const LOGO_IEEE =
  "data:image/png;base64,";

const SIGN_BHATIA =
  "data:image/png;base64,";

const SIGN_RACHITA =
  "data:image/png;base64,";

// ---------------- HELPERS ----------------
const escapeHtml = (v = "") =>
  String(v)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");

// 1 | "1" | "1st" -> 1<sup>st</sup>
const formatPosition = (position) => {
  const raw = String(position).trim();
  const num = parseInt(raw, 10);
  if (!Number.isNaN(num)) {
    const mod100 = num % 100;
    const suffix =
      mod100 >= 11 && mod100 <= 13
        ? "th"
        : { 1: "st", 2: "nd", 3: "rd" }[num % 10] || "th";
    return `${num}<sup>${suffix}</sup>`;
  }
  return escapeHtml(raw);
};

// shrink long names so they always fit on one line
const nameFontSize = (name) => {
  const len = String(name).length;
  if (len <= 22) return 29;
  return Math.max(16, Math.floor((29 * 22) / len));
};

const SIGNATORIES = {
  left: { name: "Dr. K.S. BHATIA", role: "IEEE GBPIET Student Branch<br/>Coordinator" },
  right: { name: "RACHITA PANT", role: "Branch Chair<br/>IEEE Student Branch" },
};

// ---------------- TEMPLATE ----------------
const templateCertificate = ({
  name,
  branch,
  event,
  date,
  certificateId,
  position,
}) => {
  const isWinner =
    position !== undefined && position !== null && String(position).trim() !== "";

  const certificateType = isWinner ? "OF POSITION HOLDERS" : "OF PARTICIPATION";

  const safeName = escapeHtml(name);
  const safeBranch = escapeHtml(branch);
  const safeEvent = escapeHtml(event);
  const safeDate = escapeHtml(date);
  const safeId = escapeHtml(certificateId);

  const description = isWinner
    ? `Of <b>${safeBranch}</b> For securing <b>${formatPosition(position)}</b> position and for their enthusiastic participation and valuable engagement in the <b>${safeEvent}</b> conducted on <b>${safeDate}</b> by the IEEE GBPIET Student Branch under IEEE Day Events`
    : `Of <b>${safeBranch}</b> For active participation and positive engagement during the <b>${safeEvent}</b> conducted on <b>${safeDate}</b> by IEEE GBPIET Student Branch.`;

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Abril+Fatface&family=Syne:wght@400;500;600;700&display=swap" rel="stylesheet" />
  <style>
      :root{
        --ink:#0f0a24; --teal:#5f9fa8; --rule:#5b97ad;
        --body-font:"Syne","Segoe UI",Arial,sans-serif;
        --title-font:"Abril Fatface","Playfair Display",Georgia,serif;
      }
      *{box-sizing:border-box;margin:0;padding:0}
      @page{size:962px 680px;margin:0}
      html,body{width:962px;height:680px;background:#fff;font-family:var(--body-font);color:var(--ink);
        -webkit-print-color-adjust:exact;print-color-adjust:exact}
      .certificate{position:relative;width:962px;height:680px;overflow:hidden;
        background:linear-gradient(165deg,#ffffff 0%,#fbfbfd 45%,#f3f3f9 100%)}
      .certificate img,.certificate .abs{position:absolute}
      .certificate img{display:block}

      .art{mix-blend-mode:multiply}
      .art.tl{left:0;top:0;width:268px;height:116px;
        -webkit-mask-image:linear-gradient(to right,#000 88%,transparent),linear-gradient(to bottom,#000 80%,transparent);
        -webkit-mask-composite:source-in;
        mask-image:linear-gradient(to right,#000 88%,transparent),linear-gradient(to bottom,#000 80%,transparent);
        mask-composite:intersect}
      .art.tr{left:470px;top:0;width:492px;height:106px;
        -webkit-mask-image:linear-gradient(to left,#000 92%,transparent),linear-gradient(to right,#000 85%,transparent 100%),linear-gradient(to bottom,#000 80%,transparent);
        -webkit-mask-composite:source-in;
        mask-image:linear-gradient(to left,#000 92%,transparent),linear-gradient(to right,transparent 0,#000 18%),linear-gradient(to bottom,#000 80%,transparent);
        mask-composite:intersect}
      .art.bl{left:0;top:520px;width:420px;height:160px;
        -webkit-mask-image:linear-gradient(to right,#000 88%,transparent),linear-gradient(to bottom,transparent 0,#000 18%);
        -webkit-mask-composite:source-in;
        mask-image:linear-gradient(to right,#000 88%,transparent),linear-gradient(to bottom,transparent 0,#000 18%);
        mask-composite:intersect}
      .art.br{left:800px;top:530px;width:162px;height:150px;
        -webkit-mask-image:linear-gradient(to right,transparent 0,#000 20%),linear-gradient(to bottom,transparent 0,#000 20%);
        -webkit-mask-composite:source-in;
        mask-image:linear-gradient(to right,transparent 0,#000 20%),linear-gradient(to bottom,transparent 0,#000 20%);
        mask-composite:intersect}

      .watermark{left:223px;top:237px;width:460px;opacity:.13;mix-blend-mode:multiply;filter:saturate(1.3)}
      .logo-left{left:103px;top:121px;width:105px;height:111px}
      .logo-right{left:738px;top:128px;width:177px;height:84px}
      .sig{left:290px;top:462px;width:105px;height:56px}
      .sig-rachita{left:587px;top:458px;width:100px;height:48px;object-fit:contain}

      .title{left:0;width:962px;top:96px;text-align:center;font-family:var(--title-font);font-weight:400;
        color:var(--ink);line-height:1.15;white-space:nowrap}
      .title span{display:inline-block;font-size:66px;letter-spacing:.5px}

      .subtitle{left:0;width:962px;top:182px;height:31px;display:flex;align-items:center;justify-content:center}
      .subtitle span{color:var(--teal);font-size:24px;letter-spacing:3.4px;font-weight:500;white-space:nowrap}

      .presented{left:0;width:962px;top:244px;text-align:center;font-size:21px;font-weight:400;line-height:28px}

      .name{left:131px;width:700px;top:288px;min-height:30px;text-align:center;font-size:29px;
        line-height:36px;font-weight:700;color:#000;white-space:nowrap}

      .desc{left:171px;top:348px;width:620px;text-align:center;font-size:21px;line-height:28px;font-weight:400}
      .desc sup{font-size:.6em;line-height:0;vertical-align:super}

      .sign{width:216px;text-align:center}
      .sign .rule{position:relative;height:2px;background:var(--rule);margin-bottom:5px}
      .sign .rule::before,.sign .rule::after{content:"";position:absolute;top:-1.5px;width:5px;height:5px;border-radius:50%;background:var(--rule)}
      .sign .rule::before{left:-1px}
      .sign .rule::after{right:-1px}
      .sign .who{font-size:17px;font-weight:700;line-height:24px;text-transform:uppercase;letter-spacing:.2px}
      .sign .role{font-size:13px;line-height:17px;font-weight:400}
      .sign-1{left:226px;top:517px}
      .sign-2{left:520px;top:517px}

      .certno{right:164px;top:648px;font-size:19px;line-height:26px;text-align:right;white-space:nowrap}
</style>
</head>
<body>
  <div class="certificate">
    <img alt="" class="art tl" src="${ART_TL}" />
    <img alt="" class="art tr" src="${ART_TR}" />
    <img alt="" class="art bl" src="${ART_BL}" />
    <img alt="" class="art br" src="${ART_BR}" />
    <img alt="" class="watermark" src="${WATERMARK}" />

    <img alt="GBPIET logo" class="logo-left" src="${LOGO_COLLEGE}" />
    <img alt="IEEE GBPIET Student Branch logo" class="logo-right" src="${LOGO_IEEE}" />

    <h1 class="abs title"><span>CERTIFICATE</span></h1>
    <div class="abs subtitle"><span>${certificateType}</span></div>
    <p class="abs presented">This certificate is presented to</p>
    <div class="abs name" style="font-size:${nameFontSize(name)}px">${safeName}</div>
    <p class="abs desc" style="top:${isWinner ? 336 : 348}px">${description}</p>

    <img alt="Signature" class="sig" src="${SIGN_BHATIA}" />
    <div class="abs sign sign-1">
      <div class="rule"></div>
      <div class="who">${SIGNATORIES.left.name}</div>
      <div class="role">${SIGNATORIES.left.role}</div>
    </div>

    <img alt="Signature" class="sig-rachita" src="${SIGN_RACHITA}" />
    <div class="abs sign sign-2">
      <div class="rule"></div>
      <div class="who">${SIGNATORIES.right.name}</div>
      <div class="role">${SIGNATORIES.right.role}</div>
    </div>

    <div class="abs certno">${safeId}</div>
  </div>
</body>
</html>`;
};

export default templateCertificate;
